(()=>{'use strict';
const $=id=>document.getElementById(id),M=StudentTMath,N=NormalMath,Z=M.Z975;
const chapters=['形状','厚尾','样本量','趋近正态','双尾 0.05','临界值'],keywords=['钟形 · 对称 · 中心为 0','同一边界 · 不同尾部概率','样本量 n · 自由度 ν','自由度增大 · 逐渐接近','每尾 0.025 · 中央 0.95','同一概率 · 不同临界值'];
const captions=['同一坐标下：t 的峰更低、尾更厚；两者总面积都为 1。','两者都取 ±1.960：t 分布的双尾概率更大。画面放大右尾，左尾与之对称。','本例采用单样本均值情形：ν=n−1。其他检验的自由度另算。','增大 n 使本例的 ν 增大，t 分布逐渐接近标准正态；有限自由度时仍有差别。','双尾合计 0.05，每尾 0.025；两条曲线各自的中央区间均为 95%。尾部含图外部分。','这里只比较参考区间的边界；实际使用 t 还是 Z，由统计量与前提条件决定。'];
const s={step:0,n:6,point:2.1,playing:false,converging:false},w=new PlantWorld.World($('scene'),{yaw:-.22,pitch:.13,extent:14,target:2.1});let q=M.comparison(s.n),auto=null,elapsed=0,lastN=s.n,convergeTime=0,convergeFrom=3;
const color={normal:'#237e5c',student:'#b9863c',grid:'#d4e1d4',muted:'#829582',gold:'#bb8b45'};
const mobile=()=>w.width<700;
w.sky=()=>{const c=w.ctx,g=c.createRadialGradient(w.width*.5,w.height*.5,0,w.width*.5,w.height*.5,Math.max(w.width,w.height)*.75);g.addColorStop(0,'#fcfdfb');g.addColorStop(1,'#edf3eb');c.fillStyle=g;c.fillRect(0,0,w.width,w.height)};
function formula(html){if($('formula').innerHTML!==html)$('formula').innerHTML=html}
function update(){q=M.comparison(s.n);$('sample-n').value=s.n;$('n-value').textContent=s.n;$('df-value').textContent=q.df;$('df-legend').textContent='ν='+q.df;$('point').value=s.point;$('point-value').textContent=s.point.toFixed(2);$('point-control').hidden=s.step!==5;$('progress').textContent=(s.step+1)+' / 6';$('keyword').textContent=keywords[s.step];$('caption').textContent=captions[s.step];document.body.dataset.step=String(s.step);$('prev').disabled=s.step===0;$('next').disabled=s.step===5;
 const normal='<math><mi>Z</mi><mo>∼</mo><mi>N</mi><mo>(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>)</mo><mspace width="1.5em"/><mi>T</mi><mo>∼</mo><msub><mi>t</mi><mi>ν</mi></msub></math>';
 if(s.step===2)formula('<math aria-label="单样本统计量 T 等于样本均值减原假设均值，除以样本标准差除以根号n；自由度n减1"><mi>T</mi><mo>=</mo><mfrac><mrow><mover><mi>X</mi><mo>¯</mo></mover><mo>−</mo><msub><mi>μ</mi><mn>0</mn></msub></mrow><mrow><mi>s</mi><mo>/</mo><msqrt><mi>n</mi></msqrt></mrow></mfrac><mspace width="1em"/><mi>ν</mi><mo>=</mo><mi>n</mi><mo>−</mo><mn>1</mn></math>');
 else if(s.step===3)formula('<math><mi>ν</mi><mo>→</mo><mi>∞</mi><mspace width="1em"/><msub><mi>t</mi><mi>ν</mi></msub><mo>→</mo><mi>N</mi><mo>(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>)</mo></math>');
 else if(s.step===4)formula('<math aria-label="双尾合计0.05，每尾0.025，累计概率0.975的分位数为上临界值"><mi>α</mi><mo>=</mo><mn>0.05</mn><mspace width="1em"/><mi>α</mi><mo>/</mo><mn>2</mn><mo>=</mo><mn>0.025</mn><mspace width="1em"/><mn>1</mn><mo>−</mo><mi>α</mi><mo>/</mo><mn>2</mn><mo>=</mo><mn>0.975</mn></math>');
 else if(s.step===5)formula('<math><msub><mi>c</mi><mi>Z</mi></msub><mo>=</mo><mn>1.960</mn><mspace width="1em"/><msub><mi>c</mi><mi>T</mi></msub><mo>=</mo><msub><mi>t</mi><mrow><mn>0.975</mn><mo>,</mo><mi>ν</mi></mrow></msub></math>');else formula(normal);
 $('numeric').textContent=s.step===1?`同取 ±1.960：正态双尾 0.0500　｜　t 双尾 ${q.tailAtNormal.toFixed(4)}`:s.step===4?`n=${s.n}，ν=${q.df}　｜　正态 ±1.960　｜　t ±${q.critical.toFixed(3)}`:s.step===5?`位置 ${s.point.toFixed(2)}：正态中央 95% ${Math.abs(s.point)<=Z?'以内':'以外'}　｜　t 中央 95% ${Math.abs(s.point)<=q.critical?'以内':'以外'}`:`n=${s.n}，ν=${q.df}　｜　峰高：N ${N.pdf(0).toFixed(4)}，t ${M.pdf(0,q.df).toFixed(4)}`;
 $('description').textContent=keywords[s.step]+'。'+captions[s.step];$('scene').dataset.df=q.df;$('scene').dataset.tCritical=q.critical.toFixed(7);$('scene').dataset.tCentral=q.central.toFixed(7);$('scene').dataset.normalCritical=Z.toFixed(7);document.querySelectorAll('[data-n]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.n===s.n)));
}
function pauseConvergence(){s.converging=false;const b=$('converge');if(b)b.textContent='▶ 播放趋近'}
function stop(){s.playing=false;clearInterval(auto);auto=null;$('play').textContent='▶';$('play').setAttribute('aria-pressed','false');pauseConvergence()}
function changeN(n,manual=true){if(manual)stop();s.n=Math.max(2,Math.min(201,Math.round(n)));update()}
function actions(){const a=$('stage-actions');a.replaceChildren();const button=(id,label,fn)=>{const b=document.createElement('button');b.id=id;b.textContent=label;b.onclick=fn;a.append(b);return b};if([0,1,2,3,4].includes(s.step))for(const n of [3,6,11,31,101]){const b=button('preset-n-'+n,'n='+n,()=>changeN(n));b.dataset.n=n;b.setAttribute('aria-pressed',String(s.n===n))}if(s.step===3)button('converge',s.converging?'Ⅱ 暂停趋近':'▶ 播放趋近',()=>{const resume=s.converging;stop();if(!resume){convergeFrom=3;convergeTime=0;s.converging=true;changeN(3,false);$('converge').textContent='Ⅱ 暂停趋近'}});if(s.step===5)for(const v of [0,2.1,3])button('point-'+String(v).replace('.','-'),'位置 '+v,()=>{stop();s.point=v;update()})}
function setStep(i,manual=true){if(manual)stop();else pauseConvergence();s.step=Math.max(0,Math.min(5,i));document.querySelectorAll('#steps button').forEach((b,j)=>{b.classList.toggle('active',j===s.step);b.setAttribute('aria-current',j===s.step?'step':'false')});if(s.step>=4){w.camera.yaw=0;w.camera.pitch=0;w.camera.zoom=1}actions();update();document.querySelector('#steps button.active')?.scrollIntoView({inline:'nearest',block:'nearest'})}
function label(p,text,opts={}){w.label(p,text,{size:13,...opts})}
function chart({cx=0,base=.7,half=5.2,height=4,min=-4.5,max=4.5,peak=.44,title=''}={}){const p=(x,y,z=0)=>[cx+(x-min)/(max-min)*half*2-half,base+y/peak*height,z];w.poly([p(min,0,-.16),p(max,0,-.16),p(max,0,.16),p(min,0,.16)],'#d4e1cf',{alpha:.28,lit:false,layer:-5});w.line([p(min,0),p(max,0)],'#8ca28b',1.1);const ticks=max-min>20?[-10,-5,0,5,10]:max-min>12?[-6,-3,0,3,6]:min>0?[2,3,4]:[-4,-2,0,2,4];for(const x of ticks)if(x>=min&&x<=max){w.line([p(x,0,-.16),p(x,0,.16)],color.grid,.8);w.line([p(x,0),p(x,-peak*.025)],'#819d82',1);label(p(x,0),String(x),{dy:15,size:11,color:color.muted})}for(const y of peak<.2?[.05,.1]:[.2,.4]){w.line([p(min,y),p(max,y)],color.grid,.6,{dash:[3,5],alpha:.7});label(p(min,y),y.toFixed(2),{dx:-19,size:10,color:color.muted})}w.line([p(min,0),p(min,peak)],'#afc0a9',.8);if(title)label([cx,base+height+.55,0],title,{size:15,pill:true});return {p,cx,base,half,height,min,max,peak}}
function line(c,fn,colorLine,width=3,alpha=1,dash=[]){const points=Array.from({length:401},(_,i)=>{const x=c.min+(c.max-c.min)*i/400;return c.p(x,fn(x))});w.line(points,colorLine,width,{alpha,dash})}
function area(c,fn,lo,hi,co,alpha=.2){lo=Math.max(c.min,lo);hi=Math.min(c.max,hi);if(hi<=lo)return;const pts=[c.p(lo,0)];for(let j=0;j<=160;j++){const x=lo+(hi-lo)*j/160;pts.push(c.p(x,fn(x)))}pts.push(c.p(hi,0));w.poly(pts,co,{alpha,lit:false,layer:-2})}
function boundary(c,x,fn,co,{value=true}={}){w.line([c.p(x,0),c.p(x,fn(x))],co,1.3,{dash:[4,4]});w.dot(c.p(x,0),.035,co);if(value)label(c.p(x,0),(x>=0?'+':'−')+Math.abs(x).toFixed(3),{dy:33,size:12,color:co,pill:true})}
function bracket(c,a,b,y,text,co){w.line([c.p(a,y),c.p(b,y)],co,1.7);for(const x of [a,b])w.line([c.p(x,y-c.peak*.016),c.p(x,y+c.peak*.016)],co,1.3);label(c.p((a+b)/2,y),text,{dy:17,size:12,color:co,pill:true})}
function mainChart(){return chart({base:s.step===5?1.45:mobile()?1:.7,half:mobile()?4.3:5.2,height:mobile()?5.9:3.8,max:s.step===5?Math.max(4.5,q.critical*1.13):4.5,min:s.step===5?-Math.max(4.5,q.critical*1.13):-4.5})}
function comparison(){const c=mainChart(),nu=q.df,tf=x=>M.pdf(x,nu);area(c,N.pdf,c.min,c.max,color.normal,.08);area(c,tf,c.min,c.max,color.student,.10);line(c,N.pdf,color.normal);line(c,tf,color.student);w.line([c.p(0,0),c.p(0,N.pdf(0))],'#86a786',1,{dash:[4,5]});if(s.step===0)label(c.p(0,.16),'同以 0 为对称中心',{size:15,pill:true});if(s.step===2){const y=c.base-.9;label([0,y,0],`${s.n} 个观测 − 估计 1 个均值 = ${q.df} 个自由度`,{size:mobile()?12:15,pill:true});}if(s.step===3)label(c.p(0,.16),`ν=${q.df}：越大越接近`,{size:15,pill:true});if(s.step===5){for(const sign of [-1,1]){boundary(c,sign*Z,N.pdf,color.normal,{value:false});boundary(c,sign*q.critical,tf,color.student,{value:false})}bracket(c,-Z,Z,-.065,`N：±1.960`,color.normal);bracket(c,-q.critical,q.critical,-.12,`t：±${q.critical.toFixed(3)}`,color.student);const x=s.point;w.line([c.p(x,0),c.p(x,.4)],'#6d8194',1.3,{dash:[4,4]});w.dot(c.p(x,.035),.07,'#6889a0');label(c.p(x,.37),'位置 '+x.toFixed(2),{dy:-18,size:14,color:'#5d7e95',pill:true});}}
function tails(){const c=chart({base:mobile()?1.1:.9,half:mobile()?4.25:5.2,height:mobile()?5.8:3.6,min:1.6,max:4.8,peak:.135,title:'右尾放大 · 两者边界均为 1.960'}),tf=x=>M.pdf(x,q.df);area(c,N.pdf,Z,c.max,color.normal,.20);area(c,tf,Z,c.max,color.student,.20);line(c,N.pdf,color.normal);line(c,tf,color.student);boundary(c,Z,tf,'#a4aa84');label(c.p(3.6,M.pdf(3.6,q.df)),'t 尾更厚',{dy:-30,size:16,color:color.student,pill:true});label(c.p(2.75,N.pdf(2.75)),'标准正态',{dy:24,size:13,color:color.normal,pill:true})}
function intervals(){const m=mobile(),extent=Math.max(4.5,q.critical*1.15),plots=m?[{cx:0,base:6.8,half:4.25,height:3.15},{cx:0,base:.9,half:4.25,height:3.15}]:[{cx:-3.4,base:.8,half:2.85,height:3.8},{cx:3.4,base:.8,half:2.85,height:3.8}];plots.forEach((opts,i)=>{const fn=i?x=>M.pdf(x,q.df):N.pdf,critical=i?q.critical:Z,co=i?color.student:color.normal,c=chart({...opts,min:-extent,max:extent,title:i?`t 分布 · ν=${q.df}`:'标准正态 N(0,1)'});area(c,fn,-critical,critical,co,.14);area(c,fn,c.min,-critical,color.gold,.55);area(c,fn,critical,c.max,color.gold,.55);line(c,fn,co);boundary(c,-critical,fn,co);boundary(c,critical,fn,co);label(c.p(0,.13),'中央 0.95',{size:m?14:17,color:co,pill:true});for(const sign of [-1,1]){const x=sign*(critical+(extent-critical)*.65),anchor=c.p(x,fn(x));label(anchor,'0.025',{dy:-38,size:13,color:color.gold,pill:true,leader:true})}})}
w.draw=()=>{w.extent=mobile()?10.5:s.step===4?15:14;w.target=mobile()?(s.step===4?5.2:3.7):2.15;if(s.step===1)tails();else if(s.step===4)intervals();else comparison();$('scene').dataset.drawMode=s.step===4?'own-central-95':s.step===1?'same-normal-boundary':'overlaid-densities'};
w.update=dt=>{if(s.converging){convergeTime+=dt;const t=Math.min(1,convergeTime/6),n=Math.round(convergeFrom*Math.exp(Math.log(201/convergeFrom)*t));if(n!==lastN){lastN=n;changeN(n,false)}if(t===1)pauseConvergence()}};
chapters.forEach((name,i)=>{const b=document.createElement('button');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${name}`;b.onclick=()=>setStep(i);$('steps').append(b)});
$('sample-n').oninput=e=>changeN(+e.target.value);$('point').oninput=e=>{stop();s.point=+e.target.value;update()};$('prev').onclick=()=>setStep(s.step-1);$('next').onclick=()=>setStep(s.step+1);$('front').onclick=()=>{w.camera.yaw=0;w.camera.pitch=0;w.camera.zoom=1};$('tilt').onclick=()=>{if(Math.abs(w.camera.yaw)+Math.abs(w.camera.pitch)<.03){w.camera.yaw=-.32;w.camera.pitch=.2}else{$('front').click()}};$('reset').onclick=()=>{stop();s.n=6;s.point=2.1;w.resetView();setStep(0)};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};$('play').onclick=()=>{if(s.playing){stop();return}if(s.step===5)setStep(0);s.playing=true;$('play').textContent='Ⅱ';$('play').setAttribute('aria-pressed','true');elapsed=0;auto=setInterval(()=>{if(s.step===3){if(!s.converging&&elapsed===0){convergeFrom=3;convergeTime=0;s.converging=true;$('converge').textContent='Ⅱ 暂停趋近'}}elapsed++;if(elapsed>=8){elapsed=0;if(s.step===5)stop();else setStep(s.step+1,false)}},1000)};w.onInteract=()=>stop();document.addEventListener('keydown',e=>{if(e.target===$('scene')||['INPUT','TEXTAREA','BUTTON'].includes(e.target.tagName))return;if(e.key==='ArrowRight')setStep(s.step+1);if(e.key==='ArrowLeft')setStep(s.step-1)});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
window.studentDiagnostics={get state(){return {...s}},get comparison(){return {...q}},get camera(){return {...w.camera}},get tailCoverage(){return {normal:[-Z,Z],student:[-q.critical,q.critical]}}};setStep(0);
})();
